68	export function BottomNavigation() {
69	  const [location, setLocation] = useLocation();
70	  const [, startTransition] = useTransition();
71	
72	  /* dockRef goes on the 280 px bar — identical to SmartTransitions trackRef.
73	     The indicator is a child of that bar so its `left` is relative to the bar. */
74	  const dockRef  = useRef<HTMLDivElement>(null);
75	  const btnRefs  = useRef<(HTMLButtonElement | null)[]>([]);
76	  const mounted  = useRef(false);
77	  const [indLeft,   setIndLeft]   = useState(0);
78	  const [animating, setAnimating] = useState(false);
79	  const [mode,      setModeState] = useState<'retail' | 'property' | 'trades'>(readMode);
80	  const [collapsed, setCollapsed] = useState(false);
81	  const [navWidth,  setNavWidth]  = useState(() => Math.min(320, window.innerWidth - 32));
82	  const idleTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
83	
84	  /* Keep nav width in sync with viewport resizes */
85	  useEffect(() => {
86	    const onResize = () => setNavWidth(Math.min(320, window.innerWidth - 32));
87	    window.addEventListener('resize', onResize);
88	    return () => window.removeEventListener('resize', onResize);
89	  }, []);
90	
91	  /* Keep stored mode in sync with route */
92	  useEffect(() => {
93	    if (location.startsWith('/trades')) {
94	      saveMode('trades'); setModeState('trades');
95	    } else if (location.startsWith('/property')) {
96	      saveMode('property'); setModeState('property');
97	    } else if (RETAIL_NAV_PATHS.includes(location) && location !== '/settings') {
98	      saveMode('retail'); setModeState('retail');
99	    }
100	  }, [location]);
101	
102	  const isTradesMode   = location.startsWith('/trades') || mode === 'trades';
103	  const isPropertyMode = !isTradesMode && (location.startsWith('/property') || mode === 'property');
104	  const items = isTradesMode ? TRADES_ITEMS : isPropertyMode ? PROPERTY_ITEMS : RETAIL_ITEMS;
105	  const navPalette = isTradesMode
106	    ? { dock: TRADES_DOCK, active: TRADES_ACTIVE, dim: TRADES_DIM }
107	    : { dock: DOCK_BG, active: BLUE, dim: BLUE_DIM };
108	
109	  const onRetailPage   = RETAIL_NAV_PATHS.includes(location);
110	  const onPropertyPage = location.startsWith('/property');
111	  // Show on merchant trades pages, but not the public client quote page (/trades/quote/:token).
112	  const onTradesPage   = location.startsWith('/trades') && !location.startsWith('/trades/quote/');
113	  const showNav = onRetailPage || onPropertyPage || onTradesPage;
114	
115	  const activeIdx = items.findIndex(({ path }) => {
116	    if (path === '/dashboard' || path === '/property' || path === '/trades') return location === path;
117	    if (path === '/settings'  || path === '/terminal' || path === '/trades/terminal') return location === path;
118	    return location === path || location.startsWith(path + '/');
119	  });
120	
121	  /* calcLeft measures relative to dockRef (the 280 px bar) — same as SmartTransitions.
122	     The indicator is a child of that bar so this gives the correct `left` value. */
123	  const calcLeft = (idx: number) => {
124	    const btn  = btnRefs.current[Math.max(0, idx)];
125	    const dock = dockRef.current;
126	    if (!btn || !dock) return indLeft;
127	    const b = btn.getBoundingClientRect();
