132	  /* Exactly mirrors SmartTransitions Dock useEffect */
133	  useEffect(() => {
134	    if (!showNav) return;
135	    const idx = Math.max(0, activeIdx);
136	    if (!mounted.current) {
137	      setIndLeft(calcLeft(idx));
138	      requestAnimationFrame(() => { mounted.current = true; });
139	      return;
140	    }
141	    setAnimating(true);
