manualChunks(id) {
  // Rollup virtual modules (\0commonjsHelpers.js, \0vite/... helpers) are
  // imported by nearly every chunk. Left unassigned, Rollup can inline
  // them into whichever chunk it visits first — if that's a lazy chunk
  // (it landed in vendor-pdf), every other chunk gains a static import of
  // that 1.4 MB chunk and it loads eagerly. Pin them to a tiny shared
  // chunk with no imports of its own so nothing heavy rides along.
  if (id.startsWith("\0") || id.includes("commonjsHelpers")) return "helpers";
  if (!id.includes("node_modules")) return undefined;

