import baseConfig from "./vite.config";
import { defineConfig } from "vite";
import fs from "fs";

export default defineConfig({
  ...(baseConfig as any),
  plugins: [
    ...(baseConfig as any).plugins,
    {
      name: "chunk-report",
      generateBundle(this: any, _opts: any, bundle: any) {
        const pdfChunk: any = Object.values(bundle).find(
          (c: any) => c.type === "chunk" && c.fileName.includes("vendor-pdf"),
