          const info = this.getModuleInfo(id);
          if (!info) continue;
          for (const imp of info.importers) {
            if (!inPdf.has(imp)) {
              out.push(`${imp.replace(/^.*node_modules\//, "nm:")}  ->  ${id.replace(/^.*node_modules\//, "nm:")}`);
            }
