1	const CACHE_NAME = 'taptpay-v3';
2	const STATIC_CACHE = 'taptpay-static-v3';
3	
4	const STATIC_ASSETS = [
5	  '/icons/icon-192x192.png',
6	  '/og-image.png'
7	];
8	
9	self.addEventListener('install', (event) => {
10	  event.waitUntil(
11	    caches.open(STATIC_CACHE)
12	      .then((cache) => cache.addAll(STATIC_ASSETS))
13	      .then(() => self.skipWaiting())
14	  );
15	});
16	
17	self.addEventListener('activate', (event) => {
18	  event.waitUntil(
19	    caches.keys().then((cacheNames) => {
20	      return Promise.all(
21	        cacheNames
22	          .filter((name) => name !== CACHE_NAME && name !== STATIC_CACHE)
23	          .map((name) => caches.delete(name))
24	      );
25	    }).then(() => self.clients.claim())
26	  );
27	});
28	
29	self.addEventListener('push', (event) => {
30	  if (!event.data) return;
31	
32	  let payload;
33	  try {
34	    payload = event.data.json();
35	  } catch (e) {
36	    payload = { title: 'TaptPay', body: event.data.text() };
37	  }
38	
39	  const status = payload.data?.status || '';
40	  const isCompleted = status === 'completed';
41	  const isFailed = status === 'failed';
42	
43	  const vibratePattern = isCompleted
44	    ? [80, 40, 80, 40, 200]
45	    : isFailed
46	    ? [300]
47	    : [100, 50, 100];
48	
49	  const actions = isCompleted
50	    ? [{ action: 'view', title: '📊 View Transactions' }]
51	    : isFailed
52	    ? [{ action: 'view', title: '🔄 Check Status' }, { action: 'dismiss', title: 'Dismiss' }]
53	    : [{ action: 'view', title: '👁 Open Terminal' }, { action: 'dismiss', title: 'Dismiss' }];
54	
55	  const options = {
56	    body: payload.body || '',
57	    icon: '/icons/icon-192x192.png',
58	    badge: '/icons/icon-72x72.png',
59	    tag: payload.tag || `taptpay-${status || 'update'}`,
60	    data: { ...(payload.data || {}), url: isCompleted ? '/transactions' : '/terminal' },
61	    vibrate: vibratePattern,
62	    requireInteraction: isCompleted,
63	    silent: false,
64	    actions,
65	  };
66	
67	  event.waitUntil(
68	    self.registration.showNotification(payload.title || 'TaptPay', options)
69	  );
70	});
71	
72	self.addEventListener('notificationclick', (event) => {
73	  event.notification.close();
74	
75	  if (event.action === 'dismiss') return;
76	
77	  const urlToOpen = new URL(
78	    event.notification.data?.url || '/terminal',
79	    self.location.origin
80	  ).href;
81	
82	  event.waitUntil(
83	    clients.matchAll({ type: 'window', includeUncontrolled: true })
84	      .then((clientList) => {
85	        for (const client of clientList) {
86	          if (client.url.startsWith(self.location.origin) && 'focus' in client) {
87	            client.focus();
88	            if ('navigate' in client) client.navigate(urlToOpen);
89	            return;
90	          }
91	        }
92	        return clients.openWindow(urlToOpen);
93	      })
94	  );
95	});
96	
97	self.addEventListener('fetch', (event) => {
98	  const { request } = event;
99	  const url = new URL(request.url);
100	
101	  if (request.method !== 'GET') return;
102	  if (url.pathname.startsWith('/api/')) return;
103	
104	  if (url.pathname.match(/\.(js|css|woff2?|ttf|eot|svg|png|jpg|jpeg|gif|ico)$/)) {
105	    // Network-first with cache fallback: always try to get the freshest
106	    // asset first, only falling back to the cached copy if the network is
107	    // unavailable. This avoids serving stale JS/CSS/images indefinitely to
108	    // returning visitors after a new deploy (previously this was
109	    // cache-first-forever, which caused the landing page to look outdated
110	    // for anyone who had visited before, until the cache name was bumped).
111	    event.respondWith(
112	      fetch(request)
113	        .then((response) => {
114	          if (response.ok) {
115	            const clone = response.clone();
116	            caches.open(STATIC_CACHE).then((cache) => cache.put(request, clone));
117	          }
118	          return response;
119	        })
120	        .catch(() => caches.open(STATIC_CACHE).then((cache) => cache.match(request)))
121	    );
122	    return;
123	  }
124	
125	  event.respondWith(
126	    fetch(request).catch(() => caches.match(request))
127	  );
128	});
